body.script:
(function () {
    "use strict";
    var url = document.getElementById("resta-tracking").getAttribute("data-url");
    var known = null, audio = null;
    function chime() {
        try {
            audio = audio || new (window.AudioContext || window.webkitAudioContext)();
            [880, 1175].forEach(function (f, i) {
                var o = audio.createOscillator(), g = audio.createGain();
                o.frequency.value = f; o.connect(g); g.connect(audio.destination);
                var t = audio.currentTime + i * 0.22;
                g.gain.setValueAtTime(0.0001, t); g.gain.exponentialRampToValueAtTime(0.3, t + 0.02);
                g.gain.exponentialRampToValueAtTime(0.0001, t + 0.35); o.start(t); o.stop(t + 0.4);
            });
        } catch (e) { /* no audio on this device */ }
    }
    function render(box, list, fresh) {
        var el = document.querySelector("#" + box + " .nums");
        el.innerHTML = "";
        if (!list.length) {
            var p = document.createElement("div"); p.className = "empty";
            p.textContent = box === "ready" ? "لا توجد طلبات جاهزة الآن" : "لا توجد طلبات قيد التحضير";
            el.appendChild(p); return;
        }
        list.forEach(function (n) {
            var d = document.createElement("div"); d.className = "num" + (fresh && fresh.indexOf(n) >= 0 ? " fresh" : "");
            d.textContent = n; el.appendChild(d);
        });
    }
    function tick() {
        fetch(url, { cache: "no-store" }).then(function (r) { return r.json(); }).then(function (data) {
            var fresh = known ? data.ready.filter(function (n) { return known.indexOf(n) < 0; }) : [];
            render("preparing", data.preparing); render("ready", data.ready, fresh);
            if (fresh.length) { chime(); }
            known = data.ready;
            document.getElementById("status").textContent = "";
        }).catch(function () {
            var s = document.getElementById("status"); s.className = "offline"; s.textContent = "جاري إعادة الاتصال…";
        });
    }
    function clock() {
        document.getElementById("clock").textContent = new Date().toLocaleTimeString("ar-SA", { hour: "2-digit", minute: "2-digit" });
    }
    document.addEventListener("click", function () { chime(); }, { once: true });
    tick(); clock(); setInterval(tick, 3000); setInterval(clock, 15000);
})();
